#!/usr/bin/env bash
#
# A runbook script walks a paged engineer through one mitigation, one stage
# per screen. Generated by the writing-runbooks skill. The runbook page runs it
# with one line, pinned to a commit:
#
#   curl -fsSL https://raw.githubusercontent.com/<owner>/<repo>/<sha>/runbooks/<alert>/mitigate.sh | bash
#
# Everything above the STAGES marker is the runbook library: copy it as is.
# Author the stages below the marker.

set -uo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Runbook library
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# The author sets these at the top of the stages section.
TOTAL_STAGES=0
ESCALATE="the on-call lead"

# Answers come from the terminal, not from stdin: with curl | bash, stdin is
# the script itself. Without a terminal every answer is "no".
ANSWERS="${RUNBOOK_ANSWERS:-/dev/tty}"

_STAGE_INDEX=0
_LOG=()

_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

_answer() {
  local reply="" status=0
  { read -r reply <&3; } 2>/dev/null || status=1
  printf '%s' "$reply"
  return "$status"
}

_log() { _LOG+=("$(date -u +%H:%MZ) $1"); }

_summary() {
  (( ${#_LOG[@]} )) || return 0
  printf '\n  %sPaste this in the incident channel:%s\n\n' "$BOLD" "$RESET"
  local line
  for line in "${_LOG[@]}"; do printf '    %s\n' "$line"; done
  printf '\n'
}

banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s steps. One step per screen.\n' "$DIM" "$TOTAL_STAGES"
  printf '  Nothing changes production until you type yes.\n'
  printf '  Ctrl-C stops it at any time.%s\n\n' "$RESET"
  pause "Press Enter to start."
}

stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Step %s of %s: %s%s\n\n' "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

say()  { printf '  %s\n' "$1"; }
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }
ok()   { printf '  %s✓ %s%s\n' "$GREEN" "$1" "$RESET"; }

open_url() {
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$1"
  { if   command -v wslview      >/dev/null 2>&1; then wslview "$1"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$1"
    elif command -v xdg-open     >/dev/null 2>&1; then xdg-open "$1"
    elif command -v open         >/dev/null 2>&1; then open "$1"
    else false; fi
  } >/dev/null 2>&1 || warn "Open this link by hand: $1"
}

pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to go on.}" "$RESET"
  _answer >/dev/null || stuck "No terminal to answer from. Run the script in a terminal."
  printf '\n'
}

confirm() {
  printf '  %s? %s [y/N]%s ' "$YELLOW" "$1" "$RESET"
  local reply; reply=$(_answer); printf '\n'
  [[ "$reply" =~ ^[Yy] ]]
}

run() {
  printf '  %s$ %s%s\n' "$BOLD" "$1" "$RESET"
  bash -o pipefail -c "$1" </dev/null 2>&1 | sed 's/^/    /'
  local status=${PIPESTATUS[0]}
  if (( status == 0 )); then _log "ran: $1"; else _log "failed ($status): $1"; warn "That command failed."; fi
  return "$status"
}

ready() {
  until bash -c "$2" </dev/null >/dev/null 2>&1; do
    warn "$1 is not ready."
    say "Fix it in another terminal: $3"
    pause "Press Enter when done. Ctrl-C to stop."
  done
  ok "$1"
}

human() {
  warn "This changes production."
  say "It does: $1"
  say "It costs: $2"
  say "Undo: $3"
  printf '\n  %s$ %s%s\n\n' "$BOLD" "$4" "$RESET"
  printf '  %sType yes to run it. Anything else skips it:%s ' "$YELLOW" "$RESET"
  local reply; reply=$(_answer); printf '\n'
  if [[ "$reply" != "yes" ]]; then _log "skipped: $4"; note "Skipped."; return 2; fi
  run "$4"
}

stuck() {
  printf '\n  %s%s✗ Stop here. %s%s\n' "$BOLD" "$RED" "$1" "$RESET"
  printf '  %sPage %s now.%s\n' "$BOLD" "$ESCALATE" "$RESET"
  _summary
  exit 1
}

finish() {
  _clear
  printf '\n%s%s  ✓ Done%s\n' "$BOLD" "$GREEN" "$RESET"
  _summary
}

trap 'printf "\n"; warn "Stopped by Ctrl-C."; _summary; exit 130' INT
{ exec 3<"$ANSWERS"; } 2>/dev/null || exec 3</dev/null

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage per step the person takes.
# Replace the example. Set TOTAL_STAGES to the number of stages.
# Keep every stage inside run_runbook and the last line as is: bash then reads
# the whole file before the first step, so a cut-off download runs nothing.
# ──────────────────────────────────────────────────────────────────────────

run_runbook() {

TOTAL_STAGES=3
ESCALATE="the on-call lead"

banner "Restart the stuck consumer"

stage "Check your access"
ready "Cluster access" "kubectl --context prod get namespaces" "log in to the prod cluster"

stage "Confirm the cause"
run "kubectl --context prod --namespace example get pods --selector app=consumer" || stuck "The cluster did not answer."
confirm "Do you see pods with status CrashLoopBackOff?" || stuck "This runbook does not fit this alert."

stage "Restart the consumer"
human "Restarts every consumer pod." "Events wait about 2 minutes." "None needed. The pods come back by themselves." \
  "kubectl --context prod --namespace example rollout restart deployment/consumer" || stuck "The restart did not run."

finish
}

run_runbook "$@"; exit
